import React from 'react';

const About = () => {
  return (
    <section id="about" className="about">
      <div className="container">
        <h2>About Me</h2>
        <div className="about-content">
          <div className="about-text">
            <p>I'm a passionate developer with expertise in full-stack development and artificial intelligence. I enjoy building innovative solutions and exploring cutting-edge technologies.</p>
            <p>Currently focused on web development, machine learning, and creating impactful digital experiences.</p>
          </div>
          <div className="about-links">
            <a href="https://www.linkedin.com/in/rohith-r-795383297/" target="_blank" rel="noopener noreferrer" className="social-link">
              <i className="fab fa-linkedin"></i> LinkedIn
            </a>
            <a href="https://github.com/Cluster3824" target="_blank" rel="noopener noreferrer" className="social-link">
              <i className="fab fa-github"></i> GitHub
            </a>
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;
